import { Injectable, TemplateRef, Type, inject } from '@angular/core';
import { NzModalService, NzModalRef, ModalButtonOptions } from 'ng-zorro-antd/modal';

export interface HrmConfirmOptions {
  title: string;
  content?: string;
  okText?: string;
  cancelText?: string;
  danger?: boolean;
  onOk?: () => void | Promise<unknown>;
  onCancel?: () => void;
}

/** Nút hành động ở chân hộp thoại open(). Nhãn do phía gọi truyền (giữ i18n sạch). */
export type HrmModalButton = ModalButtonOptions;

/** Tuỳ chọn cho hộp thoại tuỳ biến (mở bằng open()). Không cố định text — mọi nhãn do phía gọi truyền. */
export interface HrmModalOptions<T = unknown> {
  /** Tiêu đề (chuỗi hoặc template). */
  title?: string | TemplateRef<any>;
  /** Nội dung: template ref, component, hoặc chuỗi. */
  content: TemplateRef<any> | Type<T> | string;
  /** Bề rộng — số px hoặc giá trị CSS bất kỳ ('100vw' cho toàn màn). */
  width?: number | string;
  /** Nút ở chân hộp thoại. Bỏ trống để tự ẩn footer bằng footer=null. */
  footer?: HrmModalButton[] | null;
  /** Cho phép bấm nền để đóng (mặc định true). Đặt false cho biểu mẫu/bắt buộc. */
  maskClosable?: boolean;
  /** Cho phép phím Esc để đóng (mặc định true). Đặt false cho hộp thoại bắt buộc. */
  keyboard?: boolean;
  /** Hiện nút đóng (x) ở góc (mặc định true). */
  closable?: boolean;
  /** Canh giữa theo chiều dọc. */
  centered?: boolean;
  /** Style áp cho vùng thân — ví dụ giới hạn chiều cao + cuộn. */
  bodyStyle?: Record<string, string>;
  /** Class thêm cho lớp bọc (dùng khi cần style riêng, ví dụ fullscreen). */
  wrapClassName?: string;
}

/** hrm modal — hộp thoại programmatic. Bọc NzModalService. */
@Injectable({ providedIn: 'root' })
export class HrmModalService {
  private readonly nz = inject(NzModalService);

  confirm(opts: HrmConfirmOptions): void {
    this.nz.confirm({
      nzTitle: opts.title,
      nzContent: opts.content,
      nzOkText: opts.okText ?? 'Đồng ý',
      nzCancelText: opts.cancelText ?? 'Huỷ',
      nzOkDanger: opts.danger ?? false,
      // danger → icon cảnh báo tông đỏ (destructive), khớp badge nút Xoá. Bridge tô .hrm-confirm-danger.
      nzIconType: opts.danger ? 'exclamation-circle' : undefined,
      nzWrapClassName: opts.danger ? 'hrm-confirm-danger' : undefined,
      nzOnOk: opts.onOk,
      nzOnCancel: opts.onCancel,
    });
  }

  /** Mở hộp thoại tuỳ biến (biểu mẫu, nội dung dài, toàn màn...). Trả về NzModalRef để đóng chủ động. */
  open<T = unknown>(opts: HrmModalOptions<T>): NzModalRef<T> {
    return this.nz.create<T>({
      nzTitle: opts.title,
      nzContent: opts.content,
      nzWidth: opts.width,
      nzFooter: opts.footer === undefined ? null : opts.footer,
      nzMaskClosable: opts.maskClosable ?? true,
      nzKeyboard: opts.keyboard ?? true,
      nzClosable: opts.closable ?? true,
      nzCentered: opts.centered ?? false,
      nzBodyStyle: opts.bodyStyle,
      nzWrapClassName: opts.wrapClassName,
    });
  }

  info(title: string, content?: string): void { this.nz.info({ nzTitle: title, nzContent: content }); }
  success(title: string, content?: string): void { this.nz.success({ nzTitle: title, nzContent: content }); }
  error(title: string, content?: string): void { this.nz.error({ nzTitle: title, nzContent: content }); }
  warning(title: string, content?: string): void { this.nz.warning({ nzTitle: title, nzContent: content }); }
}
